      JOIN pg_namespace n ON n.oid = c1.relnamespace
      WHERE n.nspname='public'
        AND c1.relname=t
        AND attnum = ANY (i.indkey)
    LOOP
      EXECUTE format('DROP INDEX IF EXISTS public.%I', idx.idxname);
      RAISE NOTICE 'Dropped index % on public.%', idx.idxname, t;
    END LOOP;

    BEGIN
      EXECUTE format('ALTER TABLE public.%I DROP COLUMN id_uuid', t);
      RAISE NOTICE 'Dropped column id_uuid on public.%', t;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Could not drop public.%.id_uuid: %', t, SQLERRM;
    END;
  END LOOP;
END;
END;
$$ LANGUAGE plpgsql;

