-- Fix type mismatch in v_fish_standard_clean: ensure allele_number* are text.
-- We cast transgene_alleles.allele_number to text (allele_number_canon),
-- and coalesce only text types afterwards.

create or replace view public.v_fish_standard_clean as
with vs as (
    select * from public.v_fish_standard
),

src as (
    select
        vs.fish_code,
        coalesce(vs.genotype, '') as genotype,
        coalesce(vs.genetic_background, '') as genetic_background,
        to_char(coalesce(vs.date_birth::date, null), 'YYYY-MM-DD') as birthday,
        coalesce(
            to_jsonb(vs.vs) ->> 'transgene_base_code',
            to_jsonb(vs.vs) ->> 'transgene',
            to_jsonb(vs.vs) ->> 'transgene_print', ''
        ) as transgene_base,
        coalesce(
            to_jsonb(vs.vs) ->> 'allele_code',
            to_jsonb(vs.vs) ->> 'allele_number', ''
        ) as allele_token,         -- text
        coalesce(to_jsonb(vs.vs) ->> 'allele_label', '') as allele_label_view     -- text
    from vs
),

joined as (
    select
        s.*,
        ta.allele_nickname,      -- text
        (ta.allele_number)::text as allele_number_canon,  -- FORCE text
        ta.allele_name as allele_name_canon     -- text
    from src AS s
    left join public.transgene_alleles AS ta
        on
            nullif(s.allele_token, '') is not null
            and (ta.allele_number)::text = s.allele_token::text
),

fmt as (
    select
        fish_code,
        genotype,
        genetic_background,
        birthday,
        transgene_base,
        nullif(allele_token, '') as allele_token,   -- text
        coalesce(allele_number_canon, nullif(allele_token, '')) as allele_number,  -- text
        coalesce(nullif(allele_label_view, ''), '') as allele_label,   -- text
        coalesce(
            allele_name_canon,
            case when nullif(allele_token, '') is not null then 'gu' || allele_token else '' end
        ) as allele_name,
        coalesce(allele_nickname, '') as allele_nickname,

        -- clean genotype rollup (text-only parts): transgene + (allele_number [label]); background excluded
        trim(
            regexp_replace(
                concat_ws(
                    ' ',
                    case
                        when nullif(transgene_base, '') is not null
                            then
                                transgene_base
                                || case
                                    when nullif(coalesce(allele_number_canon, allele_token, ''), '') is not null
                                        then
                                            '('
                                            || coalesce(allele_number_canon, allele_token, '')
                                            || case
                                                when nullif(allele_label, '') is not null
                                                    then ' ' || allele_label
                                                else ''
                                            end
                                            || ')'
                                    else ''
                                end
                    end
                ), '\s+', ' ', 'g'
            )
        ) as genotype_rollup_clean,

        -- pretty strings (text)
        case
            when nullif(transgene_base, '') is not null and nullif(coalesce(allele_nickname, ''), '') is not null
                then 'Tg(' || transgene_base || ')' || allele_nickname
            else ''
        end as transgene_pretty_nickname,

        case
            when nullif(transgene_base, '') is not null and nullif(coalesce(allele_name, ''), '') is not null
                then 'Tg(' || transgene_base || ')' || allele_name
            else ''
        end as transgene_pretty_name
    from joined
)

select
    fish_code,
    genotype,
    genetic_background,
    birthday,
    transgene_base,
    allele_token,
    allele_number,
    allele_label,
    allele_nickname,
    allele_name,
    transgene_pretty_nickname,
    transgene_pretty_name,
    genotype_rollup_clean
from fmt;

comment on view public.v_fish_standard_clean is
'Clean fish standard view — allele_number is global (text); enriched allele_name/nickname; pretty strings; rollup excludes background.';

