  from public.cross_instances ci
),
ci_by_plan as (
  -- plan → latest cross_instance via clutches link
  select
    c.planned_cross_id::uuid  as clutch_plan_id,
    i.*
  from public.clutches c
  join inst i on i.cross_instance_id = c.cross_instance_id
),
rows as (
