        ELSE v_nick_raw
      END
    )
    RETURNING allele_number, allele_nickname
    INTO ret_allele_number, ret_allele_nickname;

    RETURN NEXT;
    RETURN;
  END IF;

  ret_allele_number := NULL;
  ret_allele_nickname := NULL;
  RETURN NEXT;
  RETURN;
END;
