  IF v_base IS NULL THEN
    RAISE EXCEPTION 'ensure_transgene_allele: base code is required';
  END IF;

  IF v_nick IS NOT NULL AND lower(v_nick) IN ('-', 'na', 'n/a', 'none', 'null') THEN
