  END IF;

  -- Set new PK on the surrogate key
  ALTER TABLE public.tank_status_history
    ADD CONSTRAINT tank_status_history_pkey PRIMARY KEY (tsh_id);

  -- Helpful ordering index (if it doesn't exist already)
  IF NOT EXISTS (
