ON ddl_command_end
WHEN TAG IN ('CREATE VIEW','CREATE MATERIALIZED VIEW','ALTER VIEW','ALTER VIEW ALL IN SCHEMA')
EXECUTE PROCEDURE public.enforce_view_prefix_v();

