  where t.fish_code = fp.mom_fish_code
  order by t.created_at asc
  limit 1
) mom_t on true
left join lateral (
  select t.tank_code
  from public.tanks t
  where t.fish_code = fp.dad_fish_code
  order by t.created_at asc
  limit 1
) dad_t on true;

