-- v_overview_crosses_cx: CR/CL chain over TP/FP (CX scheme)
-- ─────────────────────────────────────────────────────────────────────────────
create or replace view public.v_overview_crosses_cx as
select
  ci.cross_run_code               as cr_code,
  ci.tank_pair_code               as tp_code,
  tp.fish_pair_code               as fp_code,
